package com.projectinfinity.kodi;
import com.sun.net.httpserver.HttpServer;
import java.io.*;import java.net.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class SourceCacheProbe {
 static int checks;static void need(boolean x,String why){checks++;if(!x)throw new AssertionError(why);}
 static void read(InfinityCastRelay.RemuxInput input,int bytes,int start)throws Exception{byte[] b=new byte[65536];int done=0;while(done<bytes){int n=input.read(b,Math.min(b.length,bytes-done));need(n>0,"read progress");for(int i=0;i<n;i++)if(b[i]!=(byte)((start+done+i)*31))throw new AssertionError("incorrect source byte");done+=n;}}
 public static void main(String[] args)throws Exception{
  final int length=40*1024*1024;AtomicInteger epoch=new AtomicInteger();AtomicBoolean weak=new AtomicBoolean();HttpServer origin=HttpServer.create(new InetSocketAddress("127.0.0.1",0),4);origin.setExecutor(Executors.newCachedThreadPool(r->{Thread t=new Thread(r);t.setDaemon(true);return t;}));
  origin.createContext("/movie.mp4",e->{try{String range=e.getRequestHeaders().getFirst("Range");int from=range==null?0:Integer.parseInt(range.substring(6,range.length()-1));e.getResponseHeaders().set("Content-Type","video/mp4");e.getResponseHeaders().set("ETag",(weak.get()?"W/":"")+"\"epoch"+epoch.get()+"\"");if(range!=null)e.getResponseHeaders().set("Content-Range","bytes "+from+"-"+(length-1)+"/"+length);e.sendResponseHeaders(range==null?200:206,length-from);byte[] b=new byte[65536];for(int at=from;at<length;){int n=Math.min(b.length,length-at);for(int i=0;i<n;i++)b[i]=(byte)((at+i)*31);e.getResponseBody().write(b,0,n);at+=n;}}catch(IOException closed){}finally{e.close();}});origin.start();
  InfinityCastRelay relay=null;try{CountDownLatch ready=new CountDownLatch(1);AtomicReference<String> failure=new AtomicReference<>();relay=InfinityCastRelay.start(InetAddress.getLoopbackAddress(),InfinityCastSource.parse("http://127.0.0.1:"+origin.getAddress().getPort()+"/movie.mp4"),(r,m,f)->{failure.set(f);ready.countDown();});need(ready.await(6,TimeUnit.SECONDS)&&failure.get()==null,"relay prepared");
   InfinityCastRelay.RemuxInput input=relay.new RemuxInput();input.budget(134217728);read(input,131072,0);long originBytes=input.usage()[0];input.seek(0,0);read(input,65536,0);need(input.usage()[0]==originBytes&&input.usage()[4]==65536,"cached replay has no origin charge");read(input,131072,65536);need(input.usage()[2]==1,"live response cursor independent of replay cursor");
   input.seek(1024*1024,0);read(input,65536,1024*1024);need(input.usage()[2]==2,"cold seek reconnects");input.seek(0,0);read(input,65536,0);need(input.usage()[2]==2,"strong ETag preserves verified cache");input.close();
   input=relay.new RemuxInput();input.budget(134217728);read(input,length,0);java.lang.reflect.Field pages=input.getClass().getDeclaredField("cache");pages.setAccessible(true);need(((java.util.Map<?,?>)pages.get(input)).size()==512,"32 MiB hard source cache");input.close();
   input=relay.new RemuxInput();input.budget(4);read(input,4,0);input.seek(0,0);read(input,4,0);input.seek(90000,0);try{input.read(new byte[1],1);throw new AssertionError("seek reset quota");}catch(IOException expected){need(expected.getMessage().equals("mkv_source_read_limit"),"origin hard limit retained");}input.close();
   input=relay.new RemuxInput();input.budget(134217728);read(input,32,0);epoch.incrementAndGet();input.seek(90000,0);try{input.read(new byte[1],1);throw new AssertionError("changed source allowed");}catch(IOException expected){need(expected.getMessage().equals("mkv_source_changed_during_remux"),"strong validator mismatch rejected");}input.close();
   weak.set(true);input=relay.new RemuxInput();input.budget(134217728);read(input,65536,0);input.seek(90000,0);read(input,32,90000);long before=input.usage()[0];input.seek(0,0);read(input,32,0);need(input.usage()[0]==before+32&&input.usage()[2]==3,"weak cache invalidated on reconnect");input.close();
   System.out.println("PASS_SOURCE_CACHE "+checks);
  }finally{if(relay!=null){relay.close();long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(6);while(InfinityCastRelay.busy()&&System.nanoTime()<end)Thread.sleep(5);need(!InfinityCastRelay.busy(),"relay retired");}origin.stop(0);}
 }
}
